from cardio_1 import a, G
# J84 — Pneumopathies interstitielles diffuses (P-02-Pneumologie). Clés absentes du glossaire au 08.10.2026.
a('PID', [('P', 'Pneumopathie'), ('I', 'Interstitielle'), ('D', 'Diffuse')], 'Pneumopathie interstitielle diffuse', '<p>Groupe de plus de deux cents maladies qui atteignent principalement l’interstitium pulmonaire, c’est-à-dire le tissu de soutien situé entre l’épithélium alvéolaire et l’endothélium capillaire. Équivalent anglais : interstitial lung disease.</p>', 'j84-interstitium')
a('FPI', [('F', 'Fibrose'), ('P', 'Pulmonaire'), ('I', 'Idiopathique')], 'Fibrose pulmonaire idiopathique', '<p>Pneumopathie interstitielle fibrosante chronique et progressive, sans cause identifiée, limitée au poumon, de l’adulte en général âgé de plus de 60 ans, associée à l’aspect UIP en tomodensitométrie ou en histologie (ATS/ERS/JRS/ALAT 2022).</p>', 'j84-fpi-def')
a('PINS', [('P', 'Pneumopathie'), ('I', 'Interstitielle'), ('N', 'Non'), ('S', 'Spécifique')], 'Pneumopathie interstitielle non spécifique', '<p>Aspect histologique et tomodensitométrique d’atteinte interstitielle homogène dans le temps, cellulaire ou fibrosante. Elle est souvent associée à une connectivite ; la forme idiopathique est rare. Équivalent anglais : NSIP.</p>', 'j84-pins')
a('UIP', [('U', 'Usual (commune)'), ('I', 'Interstitial (interstitielle)'), ('P', 'Pneumonia (pneumopathie)')], 'Pneumopathie interstitielle commune (usual interstitial pneumonia)', '<p>Aspect lésionnel de la fibrose pulmonaire idiopathique : fibrose sous-pleurale et basale, hétérogène dans le temps, avec rayon de miel et foyers fibroblastiques. Il existe aussi dans d’autres maladies (polyarthrite rhumatoïde, pneumopathie d’hypersensibilité, asbestose).</p>', 'j84-tdm-uip')
a('FPP', [('F', 'Fibrose'), ('P', 'Pulmonaire'), ('P', 'Progressive')], 'Fibrose pulmonaire progressive', '<p>Définition ATS/ERS/JRS/ALAT 2022 : chez un patient atteint d’une pneumopathie interstitielle fibrosante autre que la fibrose pulmonaire idiopathique, au moins deux critères sur trois (symptômes, fonction, imagerie) au cours de l’année écoulée, sans autre explication.</p>', 'j84-fpp')
a('JRS', [('J', 'Japanese (japonaise)'), ('R', 'Respiratory (de pneumologie)'), ('S', 'Society (société)')], 'Société japonaise de pneumologie', '<p>Coautrice, avec l’ATS, l’ERS et l’Association latino-américaine du thorax, des recommandations internationales de 2011, 2015, 2018 et 2022 sur la fibrose pulmonaire idiopathique.</p>')
a('ATS/ERS/JRS/ALAT', [('ATS', 'American Thoracic Society (Société thoracique américaine)'), ('ERS', 'European Respiratory Society (Société européenne de pneumologie)'), ('JRS', 'Japanese Respiratory Society (Société japonaise de pneumologie)'), ('ALAT', 'Asociación LatinoAmericana de Tórax (Association latino-américaine du thorax)')], 'Recommandation conjointe de quatre sociétés de pneumologie', '<p>Signature des recommandations internationales sur la fibrose pulmonaire idiopathique (2011, 2015, 2018, 2022). Ici, ALAT ne désigne pas l’alanine aminotransférase.</p>')
a('LBA', [('L', 'Lavage'), ('B', 'Broncho-'), ('A', 'Alvéolaire')], 'Lavage broncho-alvéolaire', '<p>Instillation puis réaspiration de sérum physiologique dans un segment pulmonaire au cours d’une bronchoscopie. La formule cellulaire oriente le diagnostic d’une pneumopathie interstitielle ; une lymphocytose nette évoque une pneumopathie d’hypersensibilité, une sarcoïdose ou une pneumopathie médicamenteuse.</p>', 'j84-lba')
a('KCO', [('K', 'Konstante (coefficient de transfert)'), ('CO', 'pour le monoxyde de Carbone')], 'Coefficient de transfert du monoxyde de carbone', '<p>Rapport de la capacité de diffusion (DLCO) au volume alvéolaire. Il exprime l’efficacité du transfert par litre de poumon ventilé ; il distingue une perte de volume pure d’une atteinte de la membrane ou des capillaires.</p>', 'j84-dlco')
a('MUC5B', [('MUC', 'MUCine'), ('5B', 'type 5B')], 'Gène de la mucine 5B', '<p>Gène d’une mucine sécrétée par les voies aériennes distales. Le variant de son promoteur rs35705950 est le facteur de risque génétique le plus fort connu de la fibrose pulmonaire idiopathique (Seibold, 2011).</p>', 'j84-muc5b')
a('TERT', [('TE', 'TElomerase'), ('R', 'Reverse (inverse)'), ('T', 'Transcriptase')], 'Transcriptase inverse de la télomérase', '<p>Sous-unité catalytique de la télomérase. Ses variants pathogènes raccourcissent les télomères et causent des fibroses pulmonaires familiales.</p>', 'j84-telomeres')
a('TERC', [('TE', 'TElomerase'), ('R', 'RNA (ARN)'), ('C', 'Component (composant)')], 'Composant ARN de la télomérase', '<p>Matrice d’ARN que la télomérase recopie pour allonger les télomères. Ses variants pathogènes participent aux télomèropathies.</p>', 'j84-telomeres')
a('RTEL1', [('R', 'Regulator of (régulateur de)'), ('TEL', 'TELomere (télomère)'), ('1', 'Elongation helicase 1 (hélicase d’élongation 1)')], 'Régulateur de l’élongation des télomères, hélicase 1', '<p>Hélicase nécessaire à la réplication des télomères ; ses variants pathogènes figurent parmi les causes génétiques de fibrose pulmonaire familiale.</p>', 'j84-telomeres')
a('PARN', [('P', 'Poly(A)-specific (spécifique de la queue poly-A)'), ('A', ''), ('R', 'Ribo-'), ('N', 'Nuclease (nucléase)')], 'Ribonucléase spécifique de la queue poly(A)', '<p>Enzyme de maturation de l’ARN de la télomérase ; ses variants pathogènes raccourcissent les télomères et favorisent la fibrose pulmonaire familiale.</p>', 'j84-telomeres')
a('SFTPC', [('SFTP', 'SurFacTant Protein (protéine du surfactant)'), ('C', 'C')], 'Gène de la protéine C du surfactant', '<p>Gène exprimé par les pneumocytes de type II. Ses variants provoquent un mauvais repliement protéique, un stress du réticulum endoplasmique et des fibroses pulmonaires familiales.</p>', 'j84-genetique')
a('GAP', [('G', 'Gender (sexe)'), ('A', 'Age (âge)'), ('P', 'Physiology (fonction respiratoire : CVF et DLCO)')], 'Indice pronostique sexe-âge-physiologie', '<p>Score de Ley et collaborateurs (2012) qui classe la fibrose pulmonaire idiopathique en trois stades selon le sexe, l’âge, la CVF et la DLCO. Mortalité à un an : 5,6 % au stade I, 16,2 % au stade II, 39,2 % au stade III.</p>', 'j84-gap')
a('PDE4B', [('PDE', 'PhosphoDiEstérase'), ('4B', 'de type 4, isoforme B')], 'Phosphodiestérase 4B', '<p>Enzyme qui dégrade l’AMPc dans les cellules immunitaires et les fibroblastes. Le nérandomilast l’inhibe de façon préférentielle.</p>', 'j84-d-nerandomilast')
a('VEGFR', [('VEGF', 'Vascular Endothelial Growth Factor (facteur de croissance de l’endothélium vasculaire)'), ('R', 'Receptor (récepteur)')], 'Récepteur du facteur de croissance de l’endothélium vasculaire', '<p>Récepteur à activité tyrosine kinase, cible du nintédanib. Son inhibition explique une partie du risque hémorragique du médicament.</p>', 'j84-d-nintedanib')
a('FGFR', [('FGF', 'Fibroblast Growth Factor (facteur de croissance des fibroblastes)'), ('R', 'Receptor (récepteur)')], 'Récepteur du facteur de croissance des fibroblastes', '<p>Récepteur à activité tyrosine kinase qui stimule la prolifération des fibroblastes ; cible du nintédanib.</p>', 'j84-d-nintedanib')
a('PDGFR', [('PDGF', 'Platelet-Derived Growth Factor (facteur de croissance dérivé des plaquettes)'), ('R', 'Receptor (récepteur)')], 'Récepteur du facteur de croissance dérivé des plaquettes', '<p>Récepteur à activité tyrosine kinase qui stimule la migration et la prolifération des fibroblastes ; cible du nintédanib.</p>', 'j84-d-nintedanib')
a('CCP', [('C', 'Cyclic (cycliques)'), ('C', 'Citrullinated (citrullinés)'), ('P', 'Peptides')], 'Peptides cycliques citrullinés', '<p>Antigènes utilisés pour détecter les anticorps anti-peptides citrullinés, très spécifiques de la polyarthrite rhumatoïde. Leur présence oriente une pneumopathie interstitielle vers une atteinte rhumatoïde.</p>')
a('MDA5', [('M', 'Melanoma (mélanome)'), ('D', 'Differentiation-'), ('A', 'Associated (associé à la différenciation)'), ('5', 'gène 5')], 'Protéine 5 associée à la différenciation du mélanome', '<p>Hélicase cytoplasmique de détection de l’ARN viral. Les anticorps anti-MDA5 caractérisent une dermatomyosite souvent amyopathique, exposée à une pneumopathie interstitielle rapidement progressive.</p>')
a('ISHLT', [('I', 'International'), ('S', 'Society for'), ('H', 'Heart and'), ('L', 'Lung'), ('T', 'Transplantation')], 'Société internationale de transplantation cardiaque et pulmonaire', '<p>Société savante qui publie les critères d’orientation et d’inscription des candidats à la transplantation pulmonaire (document de consensus 2021).</p>', 'j84-transplantation')
a('FDA', [('F', 'Food and'), ('D', 'Drug'), ('A', 'Administration')], 'Agence américaine des produits alimentaires et des médicaments', '<p>Autorité américaine d’autorisation des médicaments. Une autorisation américaine ne vaut pas autorisation suisse.</p>')
a('EMA', [('E', 'European (européenne)'), ('M', 'Medicines (des médicaments)'), ('A', 'Agency (agence)')], 'Agence européenne des médicaments', '<p>Agence qui évalue les médicaments pour l’Union européenne ; la Commission européenne délivre ensuite l’autorisation. Swissmedic statue séparément pour la Suisse.</p>')
a('INPULSIS', [('INPULSIS', 'nom propre des deux essais de phase 3 du nintédanib (INPULSIS-1 et INPULSIS-2), non développable lettre à lettre')], 'Essais INPULSIS (nintédanib, 2014)', '<p>Deux essais randomisés de 52 semaines contre placebo chez 1066 patients atteints de fibrose pulmonaire idiopathique : le nintédanib a réduit de moitié environ le déclin annuel de la CVF (Richeldi, 2014).</p>', 'j84-d-nintedanib')
a('ASCEND', [('ASCEND', 'nom propre de l’essai de phase 3 de la pirfénidone, non développable lettre à lettre')], 'Essai ASCEND (pirfénidone, 2014)', '<p>Essai randomisé de 52 semaines chez 555 patients : la pirfénidone a réduit de 47,9 % la proportion de patients ayant perdu au moins 10 % de CVF ou décédés (King, 2014).</p>', 'j84-d-pirfenidone')
a('CAPACITY', [('CAPACITY', 'nom propre des deux premiers essais de phase 3 de la pirfénidone, non développable lettre à lettre')], 'Essais CAPACITY (pirfénidone, 2011)', '<p>Deux essais randomisés de 72 semaines dont un seul a atteint son critère principal ; ils ont conduit à l’essai confirmatoire ASCEND (Noble, 2011).</p>', 'j84-d-pirfenidone')
a('PANTHER-IPF', [('PANTHER', 'Prednisone, Azathioprine and N-acetylcysteine: a sTudy that evaluates Response (prednisone, azathioprine et N-acétylcystéine : étude de la réponse)'), ('IPF', 'in Idiopathic Pulmonary Fibrosis (dans la fibrose pulmonaire idiopathique)')], 'Essai PANTHER-IPF (2012)', '<p>Essai randomisé interrompu prématurément : l’association prednisone, azathioprine et N-acétylcystéine augmentait la mortalité et les hospitalisations par rapport au placebo (Raghu, 2012).</p>', 'j84-panther')
a('INBUILD', [('INBUILD', 'nom propre de l’essai du nintédanib dans les fibroses progressives autres que la fibrose idiopathique, non développable lettre à lettre')], 'Essai INBUILD (nintédanib, 2019)', '<p>Essai randomisé de 663 patients atteints de pneumopathie interstitielle fibrosante progressive non idiopathique : déclin annuel de la CVF de 80,8 mL sous nintédanib contre 187,8 mL sous placebo (Flaherty, 2019).</p>', 'j84-inbuild')
a('SENSCIS', [('SENSCIS', 'Safety and Efficacy of Nintedanib in Systemic SClerosIS (sécurité et efficacité du nintédanib dans la sclérodermie systémique)')], 'Essai SENSCIS (nintédanib, 2019)', '<p>Essai randomisé chez 576 patients atteints de pneumopathie interstitielle de la sclérodermie systémique : déclin annuel de la CVF de 52,4 mL sous nintédanib contre 93,3 mL sous placebo (Distler, 2019).</p>', 'j84-connectivites')
a('FIBRONEER-IPF', [('FIBRONEER', 'nom propre du programme de phase 3 du nérandomilast, non développable lettre à lettre'), ('IPF', 'Idiopathic Pulmonary Fibrosis (fibrose pulmonaire idiopathique)')], 'Essai FIBRONEER-IPF (nérandomilast, 2025)', '<p>Essai randomisé de 1177 patients atteints de fibrose pulmonaire idiopathique, dont 77,7 % recevaient déjà un antifibrosant : différence de déclin de la CVF de 68,8 mL à 52 semaines entre 18 mg deux fois par jour et placebo (Richeldi, 2025).</p>', 'j84-d-nerandomilast')
a('FIBRONEER-ILD', [('FIBRONEER', 'nom propre du programme de phase 3 du nérandomilast, non développable lettre à lettre'), ('ILD', 'Interstitial Lung Disease (pneumopathie interstitielle)')], 'Essai FIBRONEER-ILD (nérandomilast, 2025)', '<p>Essai randomisé de 1176 patients atteints de fibrose pulmonaire progressive : différence de déclin de la CVF de 67,2 mL à 52 semaines entre 18 mg deux fois par jour et placebo (Maher, 2025).</p>', 'j84-d-nerandomilast')
a('EXAFIP', [('EX', 'EXacerbation'), ('A', 'Aiguë de la'), ('FIP', 'Fibrose Idiopathique Pulmonaire')], 'Essai EXAFIP (cyclophosphamide, 2021)', '<p>Essai randomisé français : l’ajout de cyclophosphamide intraveineux aux glucocorticoïdes dans l’exacerbation aiguë de fibrose pulmonaire idiopathique augmentait la mortalité à trois mois (45 % contre 31 %).</p>', 'j84-exacerbation')
a('ACE-IPF', [('ACE', 'AntiCoagulant Effectiveness (efficacité des anticoagulants)'), ('IPF', 'in Idiopathic Pulmonary Fibrosis (dans la fibrose pulmonaire idiopathique)')], 'Essai ACE-IPF (warfarine, 2012)', '<p>Essai randomisé interrompu : la warfarine prescrite comme traitement de la fibrose pulmonaire idiopathique augmentait la mortalité (Noth, 2012).</p>', 'j84-a-eviter')
a('J84.0', [('J84.0', 'code CIM-10-GM 2024')], 'Affections alvéolaires et pariéto-alvéolaires', '<p>Sous-catégorie traitée dans le cours J84 — Pneumopathies interstitielles diffuses : protéinose alvéolaire et microlithiase alvéolaire.</p>')
for code, title in [('J84.1', 'Autres affections pulmonaires interstitielles avec fibrose'), ('J84.8', 'Autres affections pulmonaires interstitielles précisées'), ('J84.9', 'Affection pulmonaire interstitielle, sans précision')]:
    a(code, [(code, 'code CIM-10-GM 2024')], title, '<p>Sous-catégorie traitée dans le cours J84 — Pneumopathies interstitielles diffuses. Le cinquième caractère précise l’absence (0) ou la présence (1) d’une exacerbation aiguë.</p>')
a('FIBRONEER', [('FIBRONEER', 'nom propre du programme de phase 3 du nérandomilast (essais FIBRONEER-IPF et FIBRONEER-ILD), non développable lettre à lettre')], 'Programme FIBRONEER (nérandomilast, 2025)', '<p>Deux essais randomisés de 52 semaines, l’un dans la fibrose pulmonaire idiopathique, l’autre dans la fibrose pulmonaire progressive ; tous deux ont atteint leur critère principal de déclin de la CVF.</p>', 'j84-d-nerandomilast')
a('Hamman-Rich', [('Hamman', 'Louis Hamman, médecin américain'), ('Rich', 'Arnold Rich, pathologiste américain')], 'Syndrome de Hamman-Rich', '<p>Nom historique de la pneumopathie interstitielle aiguë idiopathique, décrite en 1935 : lésion alvéolaire diffuse d’évolution rapide, sans cause identifiée, de pronostic sévère.</p>')
a('Funke-Chambour', [('Funke-Chambour', 'Manuela Funke-Chambour, pneumologue suisse, première autrice')], 'Funke-Chambour et collaborateurs, Respiration 2017', '<p>Prise de position du groupe de travail sur les maladies pulmonaires interstitielles et rares de la Société suisse de pneumologie sur le diagnostic et le traitement de la fibrose pulmonaire idiopathique en Suisse (Respiration 2017 ; 93 : 363-378).</p>')
a('CYP3A', [('CYP', 'CYtochrome P450'), ('3', 'famille 3'), ('A', 'sous-famille A')], 'Sous-famille 3A du cytochrome P450', '<p>Groupe d’isoenzymes hépatiques et intestinales, dominé par le CYP3A4, qui métabolise de nombreux médicaments. Le nérandomilast en est un substrat : un inhibiteur puissant comme l’itraconazole augmente son exposition.</p>', 'j84-interactions')
a('AmbOx', [('Amb', 'Ambulatory (ambulatoire)'), ('Ox', 'Oxygen (oxygène)')], 'Essai AmbOx (oxygène d’effort, 2018)', '<p>Essai randomisé croisé britannique chez 84 patients atteints de pneumopathie interstitielle fibrosante qui désaturaient à l’effort : l’oxygène ambulatoire a amélioré la qualité de vie liée à la maladie et la dyspnée (Visca, 2018).</p>', 'j84-oxygene')
